import { useCallback, useEffect, useMemo, useState } from 'react';

import GlobalIcon from 'assets/icons/global.svg';
import { useQuickFilter } from 'components/Filter/hooks/useQuickFilter';
import { FieldProps } from 'components/Filter/types';
import { Select } from 'components/Form';
import { FilterDataAccessor } from 'domain/Filter';
import {
  useGoogleAnalytics,
  usePageFilterApplied,
  usePageFilterData,
} from 'hooks';
import { Option } from 'models/Filters';
import { getCachedCountryAssetImageUrl, getCountryAssetImageUrl } from 'utils';

interface CountryChipImageProps {
  imageUrl: string;
  alt: string;
  dataTestId?: string;
}

const CountryChipImage: React.FC<CountryChipImageProps> = ({
  imageUrl,
  alt,
  dataTestId,
}) => {
  return (
    <img
      data-testid={dataTestId}
      src={imageUrl}
      alt={alt}
      width={16}
      height={16}
    />
  );
};

const CountryChipPlaceholder: React.FC<{
  countryCode: string;
  presetUrl?: string;
  dataTestId?: string;
}> = ({ countryCode, presetUrl, dataTestId }) => {
  const [imageUrl, setImageUrl] = useState<string | null>(
    () => presetUrl ?? getCachedCountryAssetImageUrl(countryCode) ?? null,
  );

  useEffect(() => {
    if (presetUrl) {
      setImageUrl(presetUrl);
      return undefined;
    }

    if (!countryCode || countryCode === 'ABI') {
      setImageUrl(null);
      return undefined;
    }

    const cached = getCachedCountryAssetImageUrl(countryCode);
    if (cached) {
      setImageUrl(cached);
      return undefined;
    }

    let cancelled = false;

    getCountryAssetImageUrl(countryCode).then((url) => {
      if (!cancelled) setImageUrl(url);
    });

    return () => {
      cancelled = true;
    };
  }, [countryCode, presetUrl]);

  if (countryCode === 'ABI') {
    return <img src={GlobalIcon} alt="ABI Global" width={16} height={16} />;
  }

  if (!imageUrl) return null;

  return (
    <CountryChipImage
      dataTestId={dataTestId ? `${dataTestId}-country-img` : undefined}
      imageUrl={imageUrl}
      alt={countryCode}
    />
  );
};

export const CountryQuickFilter = ({
  dataTestId,
  fieldKey,
  pageName,
  onValueChange,
  getCurrentValue,
}: FieldProps) => {
  const trackGA = useGoogleAnalytics();
  const { applied } = usePageFilterApplied(pageName);
  const zoneValue = applied.zone;
  const countryValue = applied.country;
  const { appliedDataFilters, rawData } = usePageFilterData(pageName);

  const options = useMemo(() => {
    return FilterDataAccessor.getInstance().getCountryOptions(
      appliedDataFilters,
    );
  }, [appliedDataFilters]);

  const chipCountryCode = useMemo(() => {
    if (zoneValue === 'ABI' || countryValue === 'ABI') return 'ABI';
    return String(countryValue || '');
  }, [zoneValue, countryValue]);

  const handleValueChange = (op: Option) => {
    if (!op?.value) return;

    trackGA({
      event_category: 'Country Select',
      event_action: 'Select',
      event_label: op?.value as string,
    });

    onValueChange('zone', { value: op.zone, label: op.zone });
    onValueChange(fieldKey, op);
  };

  const { handleClear } = useQuickFilter({
    fieldKey,
    pageName,
    gaCategory: 'Country Select',
    filterContext: { zone: zoneValue },
    onValueChange,
    getCurrentValue,
  });

  const getChipPlaceholder = useCallback(
    (options: Option | Option[]) => {
      const option = Array.isArray(options) ? options[0] : options;
      if (!chipCountryCode) return null;

      return (
        <CountryChipPlaceholder
          key={chipCountryCode}
          countryCode={chipCountryCode}
          presetUrl={option?.image_url}
          dataTestId={dataTestId}
        />
      );
    },
    [chipCountryCode, dataTestId],
  );

  const validOptions = useMemo(
    () =>
      options
        .filter((op) => op?.value != null && op?.label != null)
        .map((op) => ({
          value: String(op?.value),
          label: op?.quick_filter_label || op?.label,
          zone: op?.zone,
          image_url: op?.image_url,
        })),
    [options],
  );

  const validValue = useMemo(() => {
    if (!countryValue) return validOptions[0]?.value || '';
    if (zoneValue !== 'ABI' && countryValue === 'ABI') {
      const applied = {
        country: countryValue,
        zone: zoneValue,
      };
      const country = FilterDataAccessor.getInstance().getCountry(
        appliedDataFilters,
        applied,
        rawData,
      );

      return {
        value: zoneValue,
        label: country?.quick_filter_label || country?.label,
      };
    }

    return String(countryValue);
  }, [countryValue, zoneValue, validOptions, appliedDataFilters, rawData]);

  const showClearIcon =
    validValue !== validOptions[0]?.value && zoneValue !== 'ABI';

  return (
    <Select
      dataTestId={dataTestId ? `${dataTestId}-${fieldKey}` : undefined}
      id={`${fieldKey}-select-quick-filter`}
      value={validValue}
      options={validOptions}
      onValueChange={(option) => {
        const opt = Array.isArray(option) ? option[0] : option;
        handleValueChange(opt as Option);
      }}
      size="medium"
      shape="pill"
      placeholder={`Select ${fieldKey}`}
      chips
      clearChips={showClearIcon}
      onClearSingle={handleClear}
      valueLabel="Country"
      getChipPlaceholder={getChipPlaceholder}
      searchable
    />
  );
};
